verify_commands.command:
rtk env PATH="$PWD/.venv/bin:$PATH" python -c 'import ast, subprocess, sys
def norm(ref, path):
    src = subprocess.check_output(["git", "show", f"{ref}:{path}"], text=True)
    tree = ast.parse(src, type_comments=True)
    for node in ast.walk(tree):
        body = getattr(node, "body", None)
        if isinstance(body, list) and body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and isinstance(body[0].value.value, str):
            node.body = body[1:]
    return ast.dump(tree, include_attributes=False)
bad = [p for p in sys.argv[1:] if norm("HEAD^", p) != norm("HEAD", p)]
assert not bad, f"non-prose AST changes: {bad}"' scripts/_backtest/__init__.py scripts/hooks/serena_grep_reminder.py
